entries[1262975] = { ["name"] = "Rock Garden", ["text"] = "10 sec cast\nReagents:\nHeavy Stone (2), Iron Ore , Silver Bar\nCraft a Rock Garden.\n(2)\nRequires Mining\n(140)\n\nUse: Places a Rock Garden that spawns a common mining node over time, and provides all the benefits of a Lodestone. Requires a Campfire nearby.\n\nMay be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1262978] = { ["name"] = "Cookie's Feast", ["text"] = "10 sec cast\nReagents:\nMystery Meat (2), Heavy Kodo Meat , Soothing Spices\nCraft Cookie's Feast.\n(2)\nRequires Cooking\n(140)\n\nUse: Lay out Cookie's Feast that contains Stamina-boosting food. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1262980] = { ["name"] = "Greenhouse", ["text"] = "10 sec cast\nReagents:\nSimple Wood (2), Arthas' Tears , Purple Lotus\nCraft a Greenhouse.\n(2)\nRequires Herbalism\n(140)\n\nUse: Places a Greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\nMay be placed over an Incense Candle to replace it.\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1262982] = { ["name"] = "Trapper's Workbench", ["text"] = "10 sec cast\nReagents:\nSimple Wood (2), Heavy Leather (4), Iron Bar\nCraft a Trapper's Workbench.\n(2)\nRequires Skinning\n(300)\n\nUse: Places a Trapper's Workbench containing 1 trap, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.\n\nMay be placed over a Camp Chair to replace it.\n\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1262985] = { ["name"] = "Field Guide", ["text"] = "10 sec cast\nReagents:\nMedium Leather (3), Slimy Murloc Scale (2), Fine Thread\nCraft a Field Guide.\n(2)\nRequires Skinning\n(140)\n\nUse: Places a Field Guide that allows players to read it and gain Track Beasts, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.\n\nMay be placed over a Camp Chair to replace it.\n\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1262990] = { ["name"] = "Fishing Rack", ["text"] = "10 sec cast\nReagents:\nSimple Wood (2), Crystal Vial , Raw Mithril Head Trout (2)\nCraft a Fishing Rack.\n(2)\nRequires Fishing\n(140)\n\nUse: Places a Fishing Rack that grants the ability to catch uncommon fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\nMay be placed over a Fish Bowl to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1262996] = { ["name"] = "Toxin Study", ["text"] = "10 sec cast\nReagents:\nAnti-Venom , Mageweave Bandage (2), Simple Wood (2)\nCraft a Toxin Study." }
entries[1262998] = { ["name"] = "Fishing Hut", ["text"] = "10 sec cast\nReagents:\nSimple Wood (5), Bolt of Runecloth (2), Seasonal Fish Steaks\nCraft a Fishing Hut.\n(2)\nRequires Fishing\n(300)\n\nUse: Places a Fishing Hut that grants the ability to catch rare fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\nMay be placed over a Fish Bowl to replace it.\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263001] = { ["name"] = "Plague Doctor's Laboratory", ["text"] = "10 sec cast\nReagents:\nSimple Wood (2), Strong Anti-Venom (2), Heavy Runecloth Bandage (5)\nCraft a Plague Doctor's Laboratory." }
entries[1263005] = { ["name"] = "Fermenter", ["text"] = "10 sec cast\nReagents:\nLeaded Vial , Kingsblood , Swiftthistle\nCraft a Fermenter.\n(2)\nRequires Alchemy\n(140)\n\nUse: Places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. May be placed over a Mana Well to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263031] = { ["name"] = "Tanning Rack", ["text"] = "10 sec cast\nReagents:\nMedium Leather (5), Fine Thread (3), Simple Wood (2)\nCraft a Tanning Rack.\n(2)\nRequires Leatherworking\n(140)\n\nUse: Places a Tanning Rack that allows the creation of certain reagents, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.\n\nMay be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263032] = { ["name"] = "Spinning Wheel", ["text"] = "10 sec cast\nReagents:\nSimple Wood (2), Bolt of Silk Cloth (5), Fine Thread (3)\nCraft a Spinning Wheel.\n(2)\nRequires Tailoring\n(140)\n\nUse: Places a Spinning Wheel that allows the creation of certain reagents, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.\n\nMay be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263034] = { ["name"] = "Repair Bot", ["text"] = "10 sec cast\nTools: Arclight Spanner\nReagents:\nWhirring Bronze Gizmo (2), Bronze Tube , Heavy Leather\nCraft a Repair Bot.\n(2)\nRequires Engineering\n(140)\n\nUse: Summons a Repair Bot that allows you and others nearby to buy reagents and repair gear. Requires a Campfire nearby.\n\nMay be placed over a Reagent Bot to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263041] = { ["name"] = "Anvil", ["text"] = "10 sec cast\nReagents:\nBronze Bar (5), Coarse Grinding Stone (2), Medium Leather (2)\nCraft an Anvil.\n(2)\nRequires Blacksmithing\n(140)\n\nUse: Places an anvil, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby.\n\nMay be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263056] = { ["name"] = "Arcane Salvager", ["text"] = "10 sec cast\nTools: Runed Truesilver Rod\nReagents:\nVision Dust (2), Lesser Nether Essence\nCraft an Arcane Salvager.\n(2)\nRequires Enchanting\n(140)\n\nUse: Places an Arcane Salvager that enables more efficient disenchanting, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby.\n\nMay be placed over an Enchanted Lute to replace it.\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263067] = { ["name"] = "Iron Oven", ["text"] = "10 sec cast\nReagents:\nSimple Flour (10), Refreshing Spring Water (5), Soothing Spices (4)\nCraft an Iron Oven.\n(2)\nRequires Cooking\n(300)\n\nUse: Places an Iron Oven required for the most advanced cooking recipes. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263070] = { ["name"] = "Seed Hybridizer", ["text"] = "10 sec cast\nReagents:\nMountain Silversage (4), Crystal Vial , Runecloth (2)\nCraft a Seed Hybridizer.\n(2)\nRequires Herbalism\n(300)\n\nUse: Places a Seed Hybridizer that allows seeds to be multiplied or combined into rarer tiers, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\nMay be placed over an Incense Candle to replace it.\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263071] = { ["name"] = "Molten Foundry", ["text"] = "10 sec cast\nReagents:\nThorium Bar (5), Dense Stone (2), Truesilver Bar\nCraft a Molten Foundry.\n(2)\nRequires Mining\n(300)\n\nUse: Places a Molten Foundry usable for recipes that require it, and provides all the benefits of a Lodestone. Requires a Campfire nearby.\n\nMay be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263073] = { ["name"] = "Master Forge", ["text"] = "10 sec cast\nReagents:\nGolem Heart , Thorium Bar (5), Rugged Leather (2)\nCraft a Master Forge.\n(2)\nRequires Blacksmithing\n(300)\n\nUse: Places a Master Forge usable for recipes that require it, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby.\n\nMay be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263078] = { ["name"] = "Alchemy Laboratory", ["text"] = "10 sec cast\nReagents:\nLich's Index Finger , Crystal Vial , Dreamfoil (2)\nCraft an Alchemy Laboratory.\n(2)\nRequires Alchemy\n(300)\n\nUse: Places an Alchemy Laboratory usable for recipes that require it, and provides all of the benefits of a Mana Well. Requires a Campfire nearby.\n\nMay be placed over a Mana Well to replace it.\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263079] = { ["name"] = "Sewing Machine", ["text"] = "10 sec cast\nReagents:\nUndeath Engine , Rugged Leather (5), Rune Thread\nCraft a Sewing Machine.\n(2)\nRequires Leatherworking\n(300)\n\nUse: Places a Sewing Machine usable for recipes that require it, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.\n\nMay be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263080] = { ["name"] = "Loom", ["text"] = "10 sec cast\nReagents:\nBottled Screams , Bolt of Runecloth (4), Simple Wood (4)\nCraft a Loom.\n(2)\nRequires Tailoring\n(300)\n\nUse: Places a Loom usable for recipes that require it, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.\n\nMay be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263082] = { ["name"] = "Arcane Forge", ["text"] = "10 sec cast\nReagents:\nMaker's Spark , Large Brilliant Shard (2), Greater Eternal Essence (4)\nCraft an Arcane Forge.\n(2)\nRequires Enchanting\n(300)\n\nUse: Places an Arcane Forge usable for recipes that require it, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby.\n\nMay be placed over an Enchanted Lute to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[1263083] = { ["name"] = "Anarchist's Workbench", ["text"] = "10 sec cast\nTools: Arclight Spanner\nReagents:\nEssence of Anarchy , Thorium Widget (2)\nCraft an Anarchist's Workbench.\n(2)\nRequires Engineering\n(300)\n\nUse: Places an Anarchist's Workbench usable for recipes that require it. Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
