entries[1266680] = { ["name"] = "Bone Armor", ["text"] = "10% of base mana 30 yd range\nInstant\nEncases the caster in bone armor, absorbing 139 to 161 damage for 1 min. While the armor holds, spellcasting cannot be interrupted by Physical attacks." }
