entries[1266893] = { ["name"] = "SAF-T Tabs", ["text"] = "5.125 sec cast\nReagents:\nLinen Cloak , Cerulean Dye\nCrafting Reagent\n\"SAF-T brand tabs make it SAF to hand out dynamite to all your friends!\"" }
entries[1266905] = { ["name"] = "SAF-T Dynamite", ["text"] = "5.125 sec cast\nReagents:\nRough Blasting Powder (2), Linen Cloth\n\nUse: Inflicts 26 to 34 Fire damage in a 5 yd radius. (1 Min Cooldown)\n\"Easy to throw, and SAF-T too!\"" }
entries[1266906] = { ["name"] = "SAF-T Copper Bomb", ["text"] = "8 sec cast\nTools: Blacksmith Hammer\nReagents:\nCopper Bar , Handful of Copper Bolts , Rough Blasting Powder (2), Linen Cloak , SAF-T Tabs (2)\n\nUse: Inflicts 22 to 28 Fire damage and stuns targets in a 3 yd radius for 1 sec. Any damage will break the effect. (1 Min Cooldown)\n\"SAF-T Brand bombs *almost* never blow up in your hands (or your paws!)\"" }
entries[1266907] = { ["name"] = "EZ-Thro Wrap", ["text"] = "8 sec cast\nReagents:\nWool Cloth , Sulfuric Acid\nCrafting Reagent" }
entries[1266908] = { ["name"] = "EZ-Thro Copper Bomb XL", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer\nReagents:\nCopper Bar (3), Coarse Blasting Powder (4), Silver Contact , EZ-Thro Wrap\n\nUse: Inflicts 43 to 57 Fire damage and stuns targets in a 5 yd radius for 1 sec. Any damage will break the effect. (1 Min Cooldown)" }
entries[1266909] = { ["name"] = "No Slip SAF-T Padding", ["text"] = "12.5 sec cast\nReagents:\nHeavy Leather , Magenta Dye\nCrafting Reagent\n\"SAF-T Padding prevents those easy throwing accidents.\"" }
entries[1266910] = { ["name"] = "SAF-T Bronze Bomb", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer\nReagents:\nCoarse Blasting Powder (4), Bronze Bar (2), Silver Contact , Wool Cloth , No Slip SAF-T Padding\n\nUse: Inflicts 73 to 97 Fire damage and stuns targets in a 3 yd radius for 2 sec. Any damage will break the effect. (1 Min Cooldown)" }
entries[1266911] = { ["name"] = "SAF-T Jumbo Dynamite", ["text"] = "12.5 sec cast\nReagents:\nHeavy Blasting Powder (2), Wool Cloth , No Slip SAF-T Padding\n\nUse: Inflicts 128 to 172 Fire damage in a 5 yd radius. (1 Min Cooldown)\n\"If it's easy to throw, it's not SAF-T!\"" }
entries[1266912] = { ["name"] = "SAF-T Bell", ["text"] = "25 sec cast\nTools: Blacksmith Hammer\nReagents:\nBronze Bar (2), Sandpaper\nCrafting Reagent\n\"Do you know where your Sheep is?! SAF-T Knows.\"" }
entries[1266913] = { ["name"] = "Shafety Sheep", ["text"] = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nBronze Framework , Whirring Bronze Gizmo , Heavy Blasting Powder (2), Wool Cloth (2), SAF-T Bell\n\nUse: Summons an Explosive Sheep which will charge at a nearby enemy and explode for 135 to 165 damage. Lasts for 3 min or until it explodes. (1 Min Cooldown)\n\"Guaranteed to blow up only where it's SAF!\"" }
entries[1266914] = { ["name"] = "EZ-Thro Fireproof Fuse", ["text"] = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nSilver Contact , Pristine Hide\nCrafting Reagent\n\"Guaranteed not to burn!\"" }
entries[1266915] = { ["name"] = "EZ-Thro Bronze Mortar", ["text"] = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nBronze Tube (4), Iron Strut , Heavy Blasting Powder (4), Medium Leather (4), EZ-Thro Fireproof Fuse\nBinds when equipped\nUnique-EquippedTrinket\nUse: Inflicts 85 to 115 Fire damage and stuns targets in a 5 yd radius for 2 sec. Any damage will break the effect. (10 Min Cooldown)\n8 Charges\n\"Thro mo mo tar!\"" }
entries[1266916] = { ["name"] = "EZ-Thro Grenade", ["text"] = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nIron Bar , Heavy Blasting Powder , Silk Cloth , EZ-Thro Fireproof Fuse\n\nUse: Inflicts 213 to 287 Fire damage in a 5 yd radius. (1 Min Cooldown)\n\"Who needs safety when it's this easy to throw?\"" }
entries[1266917] = { ["name"] = "SAF-T Casing", ["text"] = "45 sec cast\nTools: Blacksmith Hammer\nReagents:\nMithril Casing , Heavy Leather\nCrafting Reagent\n\"Extra padding for SAF-T!\"" }
entries[1266918] = { ["name"] = "SAF-T Bomb", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nIron Bar (3), Heavy Blasting Powder (3), Silver Contact , SAF-T Casing\n\nUse: Inflicts 149 to 201 Fire damage and stuns targets in a 5 yd radius for 3 sec. Any damage will break the effect. (1 Min Cooldown)\n\"S. A. F. T. B. O. M. B. SAF-T. Bomb.\"" }
entries[1266919] = { ["name"] = "Emergency Field Cloak", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nGnomish Cloaking Device , SAF-T Casing\nBinds when picked up\nUnique-EquippedTrinket\nUse: Gives invisibility for 10 sec. (1 Hour Cooldown)\n3 Charges\n\"SAF-T means not getting caught.\"" }
entries[1266920] = { ["name"] = "Compact Critter Carrier", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHeavy Leather (10), Mithril Tube (10), Greater Nether Essence (2), Gold Power Core\nClasses: Hunter\n40\n\nUse: Place a Compact Critter Carrier for 3 min that allows Hunters in your group to access their stabled pets. (30 Min Cooldown)" }
entries[1266921] = { ["name"] = "EZ-Thro Tru-Trigger", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nTruesilver Bar , Viridian Dye\nCrafting Reagent\n\"EZ to use and almost never misfires!\"" }
entries[1266922] = { ["name"] = "Tru-Trigger Frag Bomb", ["text"] = "45 sec cast\nReagents:\nMithril Casing , Unstable Trigger , Solid Blasting Powder , EZ-Thro Tru-Trigger\n\nUse: Inflicts 149 to 201 Fire damage and stuns targets in an 8 yd radius for 2 sec. Any damage will break the effect. (1 Min Cooldown)\n\"Tru-Trigger frags enemies, not in your hands.\"" }
entries[1266923] = { ["name"] = "SAF-T Disposable Parachute", ["text"] = "45 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nParachute Cloak , SAF-T Casing\nBinds when equipped\nBack\n31 Armor\nUse: Reduces your fall speed for 10 sec. (30 Min Cooldown)\n3 Charges\n\"SAF-T in case you need to jump.\"" }
entries[1266924] = { ["name"] = "Gnomish Army Knife", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Casing , Gold Power Core , Thorium Widget (2)\n45\n\"It's got everything: a spanner, a wrench, a hammer... even a mining pick.\"" }
entries[1266925] = { ["name"] = "Loot-A-Rang", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nThorium Bar (5), Greater Eternal Essence (5)\nLoot-A-Rang\nBinds when used\n50\nRequires Engineering\n(250)\n\nUse: Retrieves the loot from a nearby corpse. (3 Sec Cooldown)" }
entries[1266926] = { ["name"] = "SAF-T Tube", ["text"] = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nThorium Bar , Azerothium Bar\nCrafting Reagent\n\"Prevents accidental oxygen exposure. That wouldn't be SAF.\"" }
entries[1266927] = { ["name"] = "SAF-T Clever Dynamite", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nDense Blasting Powder (2), Runecloth (3), SAF-T Tube\n\nUse: Inflicts 340 to 460 Fire damage in a 5 yd radius. (1 Min Cooldown)\n\"SAF-T isn't dense. It's clever!\"" }
entries[1266928] = { ["name"] = "EZ-Thro Shell", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nThorium Bar (2), Pristine Scale\nCrafting Reagent\n\"Encase your explosives in EZ to Thro thorium-plated shells.\"" }
entries[1266929] = { ["name"] = "EZ-Thro Thorium Grenade", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nThorium Widget , Thorium Bar (3), Dense Blasting Powder (3), Runecloth (3), EZ-Thro Shell\n\nUse: Inflicts 300 to 500 Fire damage and stuns targets for 3 sec in a 3 yd radius. Any damage will break the effect. (1 Min Cooldown)\n\"Anyone can use grenades with EZ-Thro!\"" }
entries[1266930] = { ["name"] = "EZ-Thro Dark Bomb", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nThorium Widget (2), Dark Iron Bar , Dense Blasting Powder (3), Runecloth (3), EZ-Thro Shell\n\nUse: Inflicts 225 to 675 Fire damage and stuns targets in a 5 yd radius for 4 sec. Any damage will break the effect. (1 Min Cooldown)\n\"So EZ, you can Thro it in the dark.\"" }
entries[1266931] = { ["name"] = "EZ-Thro Mana Bomb", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nDelicate Arcanite Converter , Thorium Bar (3), Runecloth , EZ-Thro Shell\n\nUse: Burns 675 to 1125 mana from those in the blast radius and deals 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec. (1 Min Cooldown)" }
entries[1266932] = { ["name"] = "EZ-Thro Field Transporter: Gadgetzan", ["text"] = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nUltrasafe Transporter: Gadgetzan , EZ-Thro Shell\nEZ-Thro Field Transporter: Gadgetzan\nBinds when used\nUnique-EquippedTrinket\n55\nUse: Safely transport yourself to Gadgetzan in Tanaris! Emphasis on Safe! Yup, nothing bad could ever happen while using this device! (4 Hrs Cooldown)\n3 Charges" }
entries[1266933] = { ["name"] = "SAF-T Emergency Ripper: Everlook", ["text"] = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nDimensional Ripper - Everlook , SAF-T Tube (2)\nSAF-T Emergency Ripper: Everlook\nBinds when used\nUnique-EquippedTrinket\n55\nUse: Rips the dimensional walls asunder and transports you to Everlook in Winterspring. There are technical problems that sometimes occur, but that's what Goblin Engineering is all about! (4 Hrs Cooldown)\n3 Charges" }
entries[1266934] = { ["name"] = "EZ and SAF Field Transporter: Mt. Hyjal", ["text"] = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nDimensional Transporter - Mt. Hyjal , EZ-Thro Shell , SAF-T Tube\nEZ and SAF Field Transporter: Mt. Hyjal\nBinds when used\nUnique-EquippedTrinket\n60\nUse: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n3 Charges\n\"Not only combining Goblin and Gnome tech, but also combining plans from the EZ-Thro and SAF-T corporations. Who knows if this will even work?\"" }
entries[1266935] = { ["name"] = "Ultrasafe Rechargeable Battery", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSulfuric Acid (2), Pitchblende , Viridian Dye , Thorium Bar (3), Mithril Bar , Death Lotus\nUltrasafe Rechargeable Battery\n60\n\nUse: Restores 3 charges to a SAF-T or EZ-Thro brand device in your possession that does not involve explosions. It would be completely Unsafe with explosives. (1 Min Cooldown)" }
entries[1266936] = { ["name"] = "Dimensional Transporter - Mt. Hyjal", ["text"] = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Bar (10), Truesilver Transformer , Core of Earth (4), Essence of Air (4), Legionite Bar (2)\nDimensional Transporter - Mt. Hyjal\nBinds when used\n60\nRequires Engineering\n(300)\n\nUse: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n\"A dangerous amalgamation of Goblin and Gnome engineering techniques.\"" }
entries[1266937] = { ["name"] = "Gnomish Poultryizer", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nIllusion Dust (10), Large Brilliant Shard (2), Azerothium Bar (2), Legionite Bar (2)\nGnomish Poultryizer\nBinds when picked up\nUnique-EquippedTrinket\n60\nUse: Turns the target into a chicken for 15 sec. Well, that is assuming the transmogrification polarity has not been reversed... (5 Min Cooldown)" }
entries[1266938] = { ["name"] = "Ultralight Goblin Glider", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nViridian Dye (2), Azerothium Bar (2), Pristine Scale (8), Thorium Bar (8)\nUltralight Goblin Glider\nBinds when used\nRequires Engineering\n(250)\n\nUse: Glide downward through the air for 10 sec while controlling your direction of travel. (3 Min Cooldown)" }
entries[1266939] = { ["name"] = "Gnomish Weather Machine", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nEssence of Earth (2), Essence of Fire (2), Essence of Air (2), Essence of Water (2), Death Lotus (2)\nGnomish Weather Machine NYI\nBinds when used\n60\nRequires Engineering\n(300)" }
entries[1266940] = { ["name"] = "Stealthman 52", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nEssence of Air (6), Illusion Dust (6), Torbernite (2), Legionite Bar (2), Marefoil (4)\nStealthman 52\n55\nRequires Engineering\n(250)\n\nUse: Cloaks the user in a stealth field for up to 1 min. Cannot be used in combat. The field lasts for up to 6 sec after moving. (5 Min Cooldown)\n\"Used by real secret agents.\"" }
entries[1266941] = { ["name"] = "SAF-T Nitro Boosts", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSchematic: Tinker: Nitro Boosts , SAF-T Tube (2)\nSAF-T Nitro Boosts\nBinds when equipped\nWaist\n55\nUse: Activate a set of jets to increase your movement speed by up to 160%, for up to 8 sec.\n3 Charges\n\"Rocket to safety with SAF-T.\"" }
entries[1266942] = { ["name"] = "EZ-Thro Magnetic Displacer", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSchematic: Tinker: Magnetic Displacement , EZ-Thro Shell\nEZ-Thro Magnetic Displacer\nBinds when equipped\nWaist\n55\nUse: Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\nCan only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min.\n3 Charges\n\"EZ-Thro corporation not responsible for magnets preventing grenades from being thrown.\"" }
entries[1266943] = { ["name"] = "SAF-T Teleport", ["text"] = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSchematic: Tinker: Teleport , SAF-T Tube (2)\nSAF-T Teleport\nBinds when equipped\nWaist\n55\nUse: Teleport forward 20 yds.\n3 Charges\n\"Teleport to SAF-T!\"" }
